+}
+
+/* BigBrotr owned fail-stop background-error guard. */
+
+static_assert(std::atomic<bool>::is_always_lock_free,
+              "The BigBrotr error latch must not block a native callback");
+struct BigBrotrBackgroundErrorState {
+  std::atomic<bool> failed{false};
+};
+
+struct rocksdb_bigbrotr_background_error_guard_t {
+  std::shared_ptr<BigBrotrBackgroundErrorState> state;
+};
+
+// This is deliberately not rocksdb_eventlistener_t: it has no foreign callbacks
+// or borrowed state. Options and DB keep the listener alive independently of the
+// query handle, and Options copies share the same sticky failure group.
+class BigBrotrBackgroundErrorListener final : public EventListener {
+ public:
+  explicit BigBrotrBackgroundErrorListener(
+      std::shared_ptr<BigBrotrBackgroundErrorState> state) noexcept
+      : state_(std::move(state)) {}
+
+  void OnBackgroundError(BackgroundErrorReason /* reason */,
+                         Status* status) noexcept override {
+    if (status->ok()) {
+      return;
+    }
+    // The query publishes refusal only, never a partially initialized diagnostic
+    // tuple. The caller owns status; callback completion publishes its promotion.
+    state_->failed.store(true, std::memory_order_release);
+    try {
+      if (status->severity() < Status::kFatalError) {
+        // This copy preserves code, subcode, message, retryable, data_loss and
+        // scope. It can allocate; failure must not leave a soft error running.
+        *status = Status(*status, Status::kFatalError);
+      }
+    } catch (...) {
+      std::terminate();
+    }
+  }
+
+  void OnErrorRecoveryBegin(BackgroundErrorReason /* reason */, Status status,
+                            bool* auto_recovery) noexcept override {
+    state_->failed.store(true, std::memory_order_release);
+    *auto_recovery = false;
+    status.PermitUncheckedError();
+  }
+
+ private:
+  const std::shared_ptr<BigBrotrBackgroundErrorState> state_;
+};
+
+rocksdb_bigbrotr_background_error_guard_t*
+rocksdb_bigbrotr_options_install_background_error_guard(rocksdb_options_t* opt) {
+  if (opt == nullptr || !opt->rep.listeners.empty()) {
+    return nullptr;
+  }
+  try {
+    auto state = std::make_shared<BigBrotrBackgroundErrorState>();
+    auto listener = std::make_shared<BigBrotrBackgroundErrorListener>(state);
+    auto guard = std::make_unique<rocksdb_bigbrotr_background_error_guard_t>();
+    guard->state = std::move(state);
+    std::vector<std::shared_ptr<EventListener>> listeners;
+    listeners.emplace_back(std::move(listener));
+    // All allocations precede this no-throw commit. Failed installation leaves
+    // both the existing listener vector and resume-count option unchanged.
+    opt->rep.listeners.swap(listeners);
+    opt->rep.max_bgerror_resume_count = 0;
+    return guard.release();
+  } catch (...) {
+    return nullptr;
+  }
+}
+
+unsigned char rocksdb_bigbrotr_background_error_guard_failed(
+    const rocksdb_bigbrotr_background_error_guard_t* guard) {
+  return guard == nullptr ||
+         guard->state->failed.load(std::memory_order_acquire);
+}
+
+void rocksdb_bigbrotr_background_error_guard_destroy(
+    rocksdb_bigbrotr_background_error_guard_t* guard) {
+  delete guard;
 }

