+/* BigBrotr owned fail-stop background-error guard.
+ * Install exactly once on final DB options before open; rejects any existing
+ * listener. NULL means failure, with options unchanged. Success fixes
+ * max_bgerror_resume_count=0. Do not replace/parse/mutate those options afterward.
+ * Non-OK background errors latch failure and become at least fatal, preserving
+ * their identity; automatic error recovery is vetoed. Promotion allocation
+ * failure terminates the process rather than escaping the callback.
+ * Options copies and DB own the listener independently of this query handle.
+ * Copies share sticky failure, with no reset. Destroying the handle never
+ * removes the listener. A live handle can be queried concurrently with native
+ * callbacks and after DB close; do not race handle destruction with a query.
+ * Installation is not serialized in OPTIONS files. Reinstall for each newly
+ * funded open. This does not cover foreground-only errors or custom file-scoped
+ * retryable filesystems, and does not join work or prove purge/capacity bounds.
+ */
+extern ROCKSDB_LIBRARY_API rocksdb_bigbrotr_background_error_guard_t*
+rocksdb_bigbrotr_options_install_background_error_guard(rocksdb_options_t*);
+extern ROCKSDB_LIBRARY_API unsigned char
+rocksdb_bigbrotr_background_error_guard_failed(
+    const rocksdb_bigbrotr_background_error_guard_t*);
+extern ROCKSDB_LIBRARY_API void rocksdb_bigbrotr_background_error_guard_destroy(
+    rocksdb_bigbrotr_background_error_guard_t*);
+
